import java.util.*;
import java.io.*;

public class CF552C {
  public static int powerLimit, baseNumber;
  public static HashSet<Long> powerSums;
  public static void main(String[] args) throws Exception {
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    PrintWriter out = new PrintWriter(System.out);

    String[] input = br.readLine().split(" ");
    baseNumber = Integer.parseInt(input[0]);
    long targetNumber = Long.parseLong(input[1]);

    int maxExp = 0;
    for (int i = 0; baseNumber > 2 && i < 21; i++) {
      maxExp = i;
      if (Math.pow(baseNumber, i) > 1e9) break;
    }

    powerSums = new HashSet<>();
    if (baseNumber > 2) recurse(0, 0, maxExp);

    boolean result = false;
    if (baseNumber == 2) result = true;

    for (Long val : powerSums) {
      if (val >= targetNumber && powerSums.contains(val - targetNumber)) {
        result = true;
        break;
      }
    }

    out.println(result ? "YES" : "NO");
    out.close();
  }

  static void recurse(int index, long sum, int maxExp) {
    if (index > maxExp) {
      powerSums.add(sum);
      return;
    }
    recurse(index + 1, sum + (long) Math.pow(baseNumber, index), maxExp);
    recurse(index + 1, sum, maxExp);
  }
}
