#include <bits/stdc++.h>
using namespace std;

int powerLimit, baseNumber;
unordered_set<long long> powerSums;

void recurse(int index, long long sum, int maxExp) {
    if (index > maxExp) {
        powerSums.insert(sum);
        return;
    }
    recurse(index + 1, sum + (long long)pow(baseNumber, index), maxExp);
    recurse(index + 1, sum, maxExp);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int baseNumber;
    long long targetNumber;
    cin >> baseNumber >> targetNumber;

    int maxExp = 0;
    for (int i = 0; baseNumber > 2 && i < 21; i++) {
        maxExp = i;
        if (pow(baseNumber, i) > 1e9) break;
    }

    powerSums.clear();
    if (baseNumber > 2) recurse(0, 0, maxExp);

    bool result = false;
    if (baseNumber == 2) result = true;

    for (auto val : powerSums) {
        if (val >= targetNumber && powerSums.count(val - targetNumber)) {
            result = true;
            break;
        }
    }

    cout << (result ? "YES" : "NO") << "\n";

    return 0;
}
